const icons={"Gold":"data:image/png;base64,","STR":"data:image/png;base64,","AGI":"data:image/png;base64,","INT":"data:image/png;base64,","Armor":"data:image/png;base64,","Damage":"data:image/png;base64,","Move speed":"data:image/png;base64,"};
const cols=[['Item',null],['Gold','cost'],['STR','bonus_strength'],['AGI','bonus_agility'],['INT','bonus_intellect'],['HP','bonus_health'],['Mana','bonus_mana'],['Hp Regen','bonus_health_regen|bonus_regen|hp_regen|health_regen|max_health_regen'],['Mana Regen','bonus_mana_regen|mana_regen'],['Damage','bonus_damage'],['Attack Speed','bonus_attack_speed'],['Attack Range','base_attack_range|attack_range_bonus|bonus_attack_range|attack_range|melee_attack_range'],['Move speed','bonus_movement_speed|bonus_speed|movement_speed'],['Spell Amp','spell_amp|bonus_spell_amp'],['Armor','bonus_armor|armor'],['Magic Resist','bonus_magic_resistance|magic_resistance|bonus_spell_resist|tooltip_resist'],['Status Resist','status_resistance'],['Slow Resist','slow_resistance|slow_resist|bonus_slow_resist'],['Evasion','bonus_evasion|evasion'],['Type','category'],['Combined Efficiency (%)','combined']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const items=Object.entries(DATA).filter(([k,v])=>v.dname&&!k.startsWith('recipe_')).map(([k,v])=>({...v,key:k}));let sort=1,dir=-1;
const HEADING_STATS={'STR':['+$str'],'AGI':['+$agi'],'INT':['+$int'],'HP':['+$health','+Max Health Increase'],'Mana':['+$mana','-Max Mana'],'Hp Regen':['+$hp_regen','+Max Health Regen','-Health Regeneration'],'Mana Regen':['+$mana_regen'],'Damage':['+$damage','-Attack Damage'],'Attack Speed':['+$attack','+$attack_pct','-Attack Speed'],'Move speed':['+$move_speed','+Movement Speed','+Move Speed (Ranged Heroes)','+Move Speed (Melee Heroes)'],'Armor':['+$armor','-Armor'],'Spell Amp':['+Spell Amplification','SPELL AMPLIFICATION'],'Magic Resist':['+$spell_resist'],'Status Resist':['+Status Resistance','+$status_resist'],'Slow Resist':['+Slow Resistance','+$slow_resistance'],'Evasion':['+$evasion'],'Attack Range':['+$attack_range','+$attack_range_melee','+$attack_range_all','AURA BONUS ATTACK RANGE (RANGED ONLY):']};
function statAttributes(i,n){const name=cols[n][0];return(i.attrib||[]).filter(a=>a.display&&(i.verified?HEADING_STATS[name]?.includes(a.heading):cols[n][1]?.split('|').includes(a.key)))}
function allAttributes(i){return(i.attrib||[]).filter(a=>a.display&&(i.verified?a.heading==='+$all':['bonus_all_stats','bonus_stats','all_stats'].includes(a.key)))}
function signedValue(a){const v=Number(a.value);return Number.isFinite(v)?(a.display?.startsWith('-')?-Math.abs(v):v):null}
function val(i,n){if(n===0)return i.dname;if(n===1)return i.cost??null;if(cols[n][1]==='category')return i.category;if(cols[n][1]==='combined')return calculateCombinedGoldEfficiency(i);const matches=statAttributes(i,n);if(n>=2&&n<=4){matches.push(...allAttributes(i));const selected=(i.attrib||[]).find(a=>a.heading==='+$selected_attrib');if(selected)return selected.value+' (selected)';if(!matches.length)return null;const values=matches.map(signedValue);if(values.every(v=>v!==null))return values.reduce((sum,v)=>sum+v,0);return matches.map(a=>a.value).join(' + ')}if(!matches.length)return null;return matches.map(a=>{const v=signedValue(a)??a.value;return v+(a.percentage||a.display.includes('%')?'%':'')+(cols[n][0]==='Attack Range'?' ('+(/ranged only/i.test(a.display)?'ranged':/melee only/i.test(a.display)?'melee':'melee & ranged')+(/aura/i.test(a.display)?', aura':'')+')':'')+(a.heading?.includes('Ranged Heroes')?' (ranged)':a.heading?.includes('Melee Heroes')?' (melee)':'')}).join(' + ')}

function compare(a,b,n){if(n===0||cols[n][1]==='category')return String(val(a,n)).localeCompare(String(val(b,n)));if(cols[n][0]==='Hp Regen'){const ap=String(val(a,n)).includes('%'),bp=String(val(b,n)).includes('%');if(ap!==bp)return Number(ap)-Number(bp)}return num(val(a,n))-num(val(b,n))}
function num(v){return parseFloat(Array.isArray(v)?v[0]:v)||0}
